<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue'
import { api, safeDownload } from '../api'
import { state, perform, notify, short, label, date } from '../state'
import type { RecordData } from '../types'
const llm = reactive({ enabled: false, provider: 'openai_compatible', base_url: '', model: '', max_tokens: 2048 })
const key = ref(''), configured = ref(false), loading = ref(false), clearKey = ref(false)
const bridge = ref<RecordData>({ connected: false }), pairing = ref<RecordData | null>(null), bridgeError = ref(''), chosen = ref('')
let timer: ReturnType<typeof setTimeout>, disposed = false, polling = false
const modUrl = computed(() => pairing.value?.mod_download_url ? safeDownload(pairing.value.mod_download_url) : '/api/v1/bridge/mod')
async function loadSettings() { loading.value = true; await perform('settings-read', async () => { const s = await api('/settings/llm'); Object.assign(llm, { enabled: s.enabled === true, provider: s.provider || 'openai_compatible', base_url: s.base_url || '', model: s.model || '', max_tokens: s.max_tokens || 2048 }); configured.value = s.configured === true }); loading.value = false }
async function saveSettings() {
  await perform('settings-save', async () => { const s = await api('/settings/llm', 'PUT', { ...llm, ...(key.value.trim() ? { api_key: key.value.trim() } : {}), clear_key: clearKey.value }); key.value = ''; clearKey.value = false; configured.value = s.configured === true; await loadSettings() }, '外部 API 设置已保存到本地服务；密钥只保留在当前服务进程内存。')
}
async function loadBridge() {
  if (polling || disposed) return
  polling = true
  try { bridge.value = await api('/bridge/status'); bridgeError.value = '' }
  catch (e) { bridgeError.value = e instanceof Error ? e.message : '编辑器连接状态读取失败。' }
  finally { polling = false }
}
async function pollBridge() { await loadBridge(); if (!disposed) timer = setTimeout(pollBridge, 3000) }
async function pair() { await perform('bridge-pair', async () => { pairing.value = await api('/bridge/pair', 'POST', {}); await loadBridge() }, '已建立一次性配对入口，请在真实编辑器的 PAMOs 模组中输入配对码。') }
async function disconnect() { await perform('bridge-disconnect', async () => { await api('/bridge/disconnect', 'POST', {}); pairing.value = null; await loadBridge() }, '已断开本机编辑器会话。') }
async function send() { const c = state.candidates.find(c => c.id === chosen.value); if (!c) return; await perform('bridge-send', async () => { await api(`/bridge/candidates/${c.id}/send`, 'POST', { expected_chart_sha256: c.chart_sha256 }); await loadBridge() }, '发送命令已排队，等待编辑器接收与保存回执。') }
async function copy(value: string) { try { await navigator.clipboard.writeText(value); notify('已复制到剪贴板。') } catch { notify('浏览器未允许复制，请直接选中内容复制。', 'error') } }
onMounted(() => { void loadSettings(); void pollBridge() })
onUnmounted(() => { disposed = true; clearTimeout(timer); key.value = '' })
</script>
<template>
  <div class="page-heading"><div><p class="eyebrow">CONNECTIONS & PRIVACY</p><h1>按你的选择，连接更多能力。</h1><p class="subtitle">本地生成不依赖外部 API。可选服务只提供局部建议，编辑器连接保留人工审批。</p></div><span class="badge outline">默认本地运行</span></div>
  <div class="settings-layout"><section class="panel"><div class="panel-heading"><div><p class="section-kicker">可选外部服务</p><h2>局部修订建议 API</h2></div><label class="switch-label"><input v-model="llm.enabled" type="checkbox"><span>{{ llm.enabled ? '已启用' : '未启用' }}</span></label></div><p class="small-text muted">通过兼容的模型服务获取结构化 patch 建议。每次外发前，审核页都会展示局部摘要并要求你明确确认。</p><div class="privacy-card"><span>⌁</span><div><strong>密钥仅用于当前服务会话</strong><p>密钥不会写入浏览器存储，不回显、不随项目保存。关闭本地服务后需要重新填写。</p></div></div><div class="field"><label>服务名称 / Provider</label><input v-model="llm.provider" placeholder="openai_compatible" autocomplete="off"><p class="field-hint">填写你使用的服务标识，接口需兼容服务端支持的协议。</p></div><div class="field"><label>API 基础地址</label><input v-model="llm.base_url" placeholder="https://你的服务地址/v1" type="url" autocomplete="off" spellcheck="false"></div><div class="field"><label>模型名称</label><input v-model="llm.model" placeholder="填写该服务中的真实模型名称" autocomplete="off" spellcheck="false"></div><div class="field"><label>API 密钥 <span :class="['badge', configured ? 'green' : 'amber']">{{ configured ? '当前服务进程已配置' : '尚未配置' }}</span></label><input v-model="key" type="password" :placeholder="configured ? '留空保留当前会话密钥' : '密钥仅暂存于内存'" autocomplete="new-password" autocapitalize="off" spellcheck="false"><label class="checkbox"><input v-model="clearKey" type="checkbox"><span>保存时清除当前会话密钥</span></label></div><div class="field"><label>单次最大输出 Tokens</label><input v-model.number="llm.max_tokens" type="number" min="128" max="4096" step="128"><p class="field-hint">限制输出规模；实际费用由服务商计费，本机不显示推算费用。</p></div><div class="form-footer"><button class="button secondary" :disabled="loading" @click="loadSettings">读取当前设置</button><button class="button primary" :disabled="state.busy['settings-save'] || (llm.enabled && (!llm.base_url || !llm.model || (!key && !configured)))" @click="saveSettings">{{ state.busy['settings-save'] ? '保存中…' : '保存会话设置' }}</button></div></section>
    <section class="panel bridge-panel"><div class="panel-heading"><div><p class="section-kicker">RPE NEXT BRIDGE</p><h2>让修改，回到真实编辑器。</h2></div><span :class="['badge', bridge.connected ? 'green' : '']">{{ bridge.connected ? '真实编辑器已连接' : '未连接' }}</span></div><p class="small-text muted">通过自研本地模组配对 RPE Next。配对读取编辑器当前谱面的快照；只能发送这个会话衍生且审核通过的版本。</p><ol class="bridge-steps"><li><span>1</span><div><strong>在 RPE Next 中打开待编辑谱面</strong><p>编辑器独立运行，先确认当前谱面已经保存。若尚未启动，请使用本机 Open-RPE-Next.cmd。</p><a class="button secondary small-button" href="http://127.0.0.1:4173" target="_blank" rel="noopener noreferrer">打开本机 RPE Next ↗</a></div></li><li><span>2</span><div><strong>下载并导入 PAMOs 模组</strong><p>在编辑器的模组管理中导入 .rpenmod，再打开 PAMOs Bridge 面板。</p><a class="button secondary small-button" :href="modUrl" download>↓ 下载自研 .rpenmod</a></div></li><li><span>3</span><div><strong>创建配对码，并在模组中输入</strong><p>只连接回环地址；配对码有效期由本地服务控制。</p><button class="button primary small-button" :disabled="state.busy['bridge-pair']" @click="pair">{{ state.busy['bridge-pair'] ? '正在创建…' : '创建一次性配对码' }}</button></div></li></ol><div v-if="pairing" class="pairing-card"><div class="row between"><span class="section-kicker">一次性配对码</span><button class="text-button" @click="copy(pairing.pairing_code)">复制</button></div><strong class="pairing-code">{{ pairing.pairing_code }}</strong><p>有效至 {{ date(pairing.expires_at) }}</p><label>本地 WebSocket 地址</label><div class="row between"><code>{{ pairing.ws_url }}</code><button class="text-button" @click="copy(pairing.ws_url)">复制</button></div></div><p v-if="bridgeError" class="inline-error">{{ bridgeError }}</p><div class="bridge-status"><div><span>连接会话</span><strong>{{ bridge.session_id ? short(bridge.session_id) : '尚未建立' }}</strong></div><div><span>编辑器候选快照</span><strong>{{ bridge.candidate_id ? short(bridge.candidate_id) : '尚无快照' }}</strong></div><div><span>最近响应</span><strong>{{ date(bridge.last_seen) }}</strong></div><div><span>真实保存回执</span><strong :class="bridge.save_state === 'SAVED' ? 'success-text' : ''">{{ bridge.save_state === 'SAVED' ? 'SAVED · 编辑器确认保存成功' : bridge.save_state || '尚未收到保存成功回执' }}</strong></div><div><span>待处理命令</span><strong>{{ Array.isArray(bridge.pending_commands) ? bridge.pending_commands.length : bridge.pending_commands ?? '—' }}</strong></div></div><p class="soft-callout muted">{{ bridge.detail || '未连接时，发送操作会被拒绝。排队和发送成功都不等于编辑器已保存。' }}</p><div class="field"><label>发送已审核的衍生候选</label><select v-model="chosen"><option value="" disabled>选择候选，由服务核对会话与审核状态</option><option v-for="c in state.candidates" :key="c.id" :value="c.id">{{ short(c.id) }} · {{ label(c.chart_mode) }} · {{ label(c.status) }}</option></select></div><div class="button-group"><button class="button primary" :disabled="!bridge.connected || !chosen || state.busy['bridge-send']" @click="send">发送并请求编辑器保存</button><button class="button secondary" :disabled="!bridge.connected || state.busy['bridge-disconnect']" @click="disconnect">断开会话</button><button class="text-button" @click="loadBridge">刷新状态</button></div><p class="field-hint">实时编辑器通信、撤销、保存重开和 Phira-Pro 兼容效果尚未进行本轮验收（NOT RUN）。</p></section></div>
  <section class="panel boundaries"><div><p class="section-kicker">清楚的边界</p><h2>数据、凭据与批准，都由你掌握。</h2></div><div class="boundaries-grid"><article><span>01</span><strong>音乐与谱面留在本机</strong><p>不提供自动云同步，也不会默认外发完整曲库。外部 API 只能接收你确认的局部摘要。</p></article><article><span>02</span><strong>建议不直接覆盖原件</strong><p>所有提案先校验、展示差异、人工批准，再创建新候选；每次提交重新审计。</p></article><article><span>03</span><strong>噪域保持只读</strong><p>首版不训练、生成或修改噪域。已导入的数据应保留，并明确提示兼容限制。</p></article></div></section>
</template>
